import { useCallback, useEffect, useState } from "react";

import { APPEARANCE_SETTINGS_STORAGE_KEY } from "./storageKeys";

export type AppearanceTheme = "charcoal" | "dark" | "light" | "system";
export type AppearanceAccent = "default" | "blue" | "emerald" | "purple" | "amber" | "rose";
export type AppearanceDensity = "compact" | "comfortable";

export type AppearanceSettingsState = {
  theme: AppearanceTheme;
  accentColor: AppearanceAccent;
  density: AppearanceDensity;
};

export const DEFAULT_APPEARANCE_SETTINGS: AppearanceSettingsState = {
  theme: "charcoal",
  accentColor: "default",
  density: "compact",
};

export const APPEARANCE_SETTINGS_EVENT = "ferryx:appearance-settings";

const THEMES = new Set<AppearanceTheme>(["charcoal", "dark", "light", "system"]);
const ACCENTS = new Set<AppearanceAccent>(["default", "blue", "emerald", "purple", "amber", "rose"]);
const DENSITIES = new Set<AppearanceDensity>(["compact", "comfortable"]);

function browserStorage(): Storage | null {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function normalizeAppearanceSettings(value: unknown): AppearanceSettingsState {
  const source = value && typeof value === "object" ? (value as Partial<AppearanceSettingsState>) : {};
  return {
    theme: typeof source.theme === "string" && THEMES.has(source.theme as AppearanceTheme)
      ? (source.theme as AppearanceTheme)
      : DEFAULT_APPEARANCE_SETTINGS.theme,
    accentColor: typeof source.accentColor === "string" && ACCENTS.has(source.accentColor as AppearanceAccent)
      ? (source.accentColor as AppearanceAccent)
      : DEFAULT_APPEARANCE_SETTINGS.accentColor,
    density: typeof source.density === "string" && DENSITIES.has(source.density as AppearanceDensity)
      ? (source.density as AppearanceDensity)
      : DEFAULT_APPEARANCE_SETTINGS.density,
  };
}

export function loadAppearanceSettings(storage: Storage | null = browserStorage()): AppearanceSettingsState {
  if (!storage) return { ...DEFAULT_APPEARANCE_SETTINGS };
  try {
    const raw = storage.getItem(APPEARANCE_SETTINGS_STORAGE_KEY);
    if (!raw) return { ...DEFAULT_APPEARANCE_SETTINGS };
    return normalizeAppearanceSettings(JSON.parse(raw));
  } catch {
    return { ...DEFAULT_APPEARANCE_SETTINGS };
  }
}

export function saveAppearanceSettings(
  patch: Partial<AppearanceSettingsState>,
  storage: Storage | null = browserStorage(),
): AppearanceSettingsState {
  const next = normalizeAppearanceSettings({ ...loadAppearanceSettings(storage), ...patch });
  try {
    storage?.setItem(APPEARANCE_SETTINGS_STORAGE_KEY, JSON.stringify(next));
  } catch {
    // Keep in-memory state usable even if storage is unavailable.
  }
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<AppearanceSettingsState>(APPEARANCE_SETTINGS_EVENT, { detail: next }));
  }
  return next;
}

export function resetAppearanceSettings(storage: Storage | null = browserStorage()): AppearanceSettingsState {
  try {
    storage?.removeItem(APPEARANCE_SETTINGS_STORAGE_KEY);
  } catch {
    // ignore storage failures
  }
  const next = { ...DEFAULT_APPEARANCE_SETTINGS };
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<AppearanceSettingsState>(APPEARANCE_SETTINGS_EVENT, { detail: next }));
  }
  return next;
}

function resolvedTheme(theme: AppearanceTheme): Exclude<AppearanceTheme, "system"> {
  if (theme !== "system") return theme;
  if (typeof window !== "undefined" && typeof window.matchMedia === "function") {
    return window.matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
  }
  return "dark";
}

export function applyAppearanceSettings(
  settings: AppearanceSettingsState,
  root: HTMLElement | null = typeof document !== "undefined" ? document.documentElement : null,
) {
  if (!root) return;
  const theme = resolvedTheme(settings.theme);
  root.dataset.theme = theme;
  root.dataset.themePreference = settings.theme;
  root.dataset.accent = settings.accentColor;
  root.dataset.density = settings.density;
  root.style.colorScheme = theme === "light" ? "light" : "dark";
}

export function useAppearanceSettings() {
  const [settings, setSettings] = useState<AppearanceSettingsState>(loadAppearanceSettings);

  useEffect(() => {
    const sync = (event: Event) => {
      const detail = (event as CustomEvent<AppearanceSettingsState>).detail;
      setSettings(detail ? normalizeAppearanceSettings(detail) : loadAppearanceSettings());
    };
    const storage = (event: StorageEvent) => {
      if (event.key === APPEARANCE_SETTINGS_STORAGE_KEY) setSettings(loadAppearanceSettings());
    };
    window.addEventListener(APPEARANCE_SETTINGS_EVENT, sync);
    window.addEventListener("storage", storage);
    return () => {
      window.removeEventListener(APPEARANCE_SETTINGS_EVENT, sync);
      window.removeEventListener("storage", storage);
    };
  }, []);

  const updateSettings = useCallback((patch: Partial<AppearanceSettingsState>) => {
    const next = saveAppearanceSettings(patch);
    setSettings(next);
    return next;
  }, []);

  const resetSettings = useCallback(() => {
    const next = resetAppearanceSettings();
    setSettings(next);
    return next;
  }, []);

  return { settings, updateSettings, resetSettings };
}

export function useApplyAppearanceSettings() {
  const { settings } = useAppearanceSettings();

  useEffect(() => {
    applyAppearanceSettings(settings);
    if (settings.theme !== "system" || typeof window.matchMedia !== "function") return;
    const query = window.matchMedia("(prefers-color-scheme: light)");
    const handleChange = () => applyAppearanceSettings(settings);
    query.addEventListener?.("change", handleChange);
    return () => query.removeEventListener?.("change", handleChange);
  }, [settings]);

  return settings;
}

import {
  applyAppearanceSettings,
  loadAppearanceSettings,
  saveAppearanceSettings,
  type AppearanceSettingsState,
} from "./appearanceSettings";
import { listBrowsers, setBrowserZoom } from "./browserTauri";
import { loadBrowserSettings, saveBrowserSettings } from "./browserSettings";
import { loadTerminalSettings } from "./terminalSettings";

let installed = false;

export function _resetSettingsRuntimeBridgeForTest() {
  installed = false;
}

function findSettingValue(label: string): HTMLElement | null {
  const labels = Array.from(document.querySelectorAll<HTMLElement>("div"));
  const heading = labels.find((element) => element.textContent?.trim() === label);
  const row = heading?.parentElement?.parentElement;
  if (!row) return null;
  const valueContainer = row.lastElementChild;
  return valueContainer?.querySelector<HTMLElement>("span") ?? null;
}

function syncGeneralAppearanceLabels(settings: AppearanceSettingsState) {
  const themeLabel = settings.theme === "system"
    ? "System"
    : settings.theme === "charcoal"
      ? "Charcoal"
      : settings.theme[0].toUpperCase() + settings.theme.slice(1);
  const densityLabel = settings.density === "comfortable" ? "Comfortable" : "Compact";
  const colorValue = findSettingValue("Color scheme");
  const densityValue = findSettingValue("Density");
  if (colorValue && colorValue.textContent !== themeLabel) colorValue.textContent = themeLabel;
  if (densityValue && densityValue.textContent !== densityLabel) densityValue.textContent = densityLabel;
}

function syncTerminalSourceLabel() {
  const settings = loadTerminalSettings();
  const hasLocalOverride = settings.fontFamily !== null || settings.macosOptionAsAlt !== null || settings.fontSize !== null;
  if (!hasLocalOverride) return;

  const headings = Array.from(document.querySelectorAll<HTMLElement>("h2"));
  const heading = headings.find((element) => element.textContent?.trim() === "Effective preferences");
  const source = heading?.nextElementSibling as HTMLElement | null;
  if (source && source.textContent !== "Local override") source.textContent = "Local override";
}

function syncAppearance() {
  const settings = saveAppearanceSettings(loadAppearanceSettings());
  applyAppearanceSettings(settings);
  syncGeneralAppearanceLabels(settings);
}

function syncBrowser() {
  saveBrowserSettings(loadBrowserSettings());
}

function afterReactEvent(callback: () => void) {
  window.setTimeout(callback, 0);
}

function isInsideSettingsSection(target: EventTarget | null, controlSelector: string) {
  if (!(target instanceof Element)) return false;
  const section = target.closest("section");
  return Boolean(section?.querySelector(controlSelector));
}

async function applyBrowserDefaultZoom() {
  const settings = loadBrowserSettings();
  try {
    const browsers = await listBrowsers();
    await Promise.all(browsers.map((browser) => setBrowserZoom(browser.browserId, settings.defaultZoom / 100)));
  } catch {
    // Browser runtime may not be available in web-preview mode.
  }
}

export function installSettingsRuntimeBridge() {
  if (installed || typeof window === "undefined" || typeof document === "undefined") return;
  installed = true;

  syncAppearance();

  const media = typeof window.matchMedia === "function" ? window.matchMedia("(prefers-color-scheme: light)") : null;
  const handleSystemThemeChange = () => {
    if (loadAppearanceSettings().theme === "system") syncAppearance();
  };
  media?.addEventListener?.("change", handleSystemThemeChange);

  window.addEventListener("change", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement)) return;

    if (["appearance-theme-mode", "appearance-accent-color", "appearance-density"].includes(target.id)) {
      afterReactEvent(syncAppearance);
      return;
    }
    if (["browser-search-engine", "browser-default-zoom", "browser-restore-tabs"].includes(target.id)) {
      afterReactEvent(() => {
        syncBrowser();
        if (target.id === "browser-default-zoom") void applyBrowserDefaultZoom();
      });
      return;
    }
    if (["terminal-font-family", "terminal-font-size", "terminal-scrollback"].includes(target.id)) {
      afterReactEvent(syncTerminalSourceLabel);
    }
  }, true);

  window.addEventListener("orca:terminal-settings", () => afterReactEvent(syncTerminalSourceLabel));

  window.addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const button = target.closest("button");
    if (!button) return;
    const text = button.textContent?.trim() ?? "";

    if (text === "Reset to defaults") {
      if (isInsideSettingsSection(button, "#appearance-theme-mode")) {
        afterReactEvent(syncAppearance);
      } else if (isInsideSettingsSection(button, "#browser-search-engine")) {
        afterReactEvent(() => {
          syncBrowser();
          void applyBrowserDefaultZoom();
        });
      }
    }
  }, true);
}

export const PROJECTS_STORAGE_KEY = "ferryx.projects";
export const ACTIVE_PROJECT_STORAGE_KEY = "ferryx.active-project";
export const SIDEBAR_OPEN_STORAGE_KEY = "ferryx.sidebar.open";
export const SIDEBAR_WIDTH_STORAGE_KEY = "ferryx.sidebar.width";
export const SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY = "ferryx.sidebar.collapsedProjects";
export const TERMINAL_SETTINGS_STORAGE_KEY = "ferryx.terminal.settings";
export const NOTIFICATION_SETTINGS_STORAGE_KEY = "ferryx.settings.notifications:v1";
export const APPEARANCE_SETTINGS_STORAGE_KEY = "ferryx.settings.appearance";
export const BROWSER_SETTINGS_STORAGE_KEY = "ferryx.settings.browser";

export const LEGACY_STORAGE_KEY_MAP: Record<string, string[]> = {
  [PROJECTS_STORAGE_KEY]: ["rorca.projects", "orca.projects"],
  [ACTIVE_PROJECT_STORAGE_KEY]: ["rorca.active-project", "orca.active-project"],
  [SIDEBAR_OPEN_STORAGE_KEY]: ["orca.sidebar.open", "rorca.sidebar.open"],
  [SIDEBAR_WIDTH_STORAGE_KEY]: ["orca.sidebar.width", "rorca.sidebar.width"],
  [SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY]: ["rorca.sidebar.collapsedProjects", "orca.sidebar.collapsedProjects"],
  [TERMINAL_SETTINGS_STORAGE_KEY]: ["orca.terminal.settings", "rorca.terminal.settings"],
  [NOTIFICATION_SETTINGS_STORAGE_KEY]: ["rorca:settings:notifications:v1", "orca:settings:notifications:v1"],
};

export function getMigratedItem(
  key: string,
  storage: Pick<Storage, "getItem" | "setItem"> | null = typeof window !== "undefined" && window.localStorage ? window.localStorage : null,
): string | null {
  if (!storage) return null;
  const value = storage.getItem(key);
  if (value !== null) return value;

  const legacyKeys = LEGACY_STORAGE_KEY_MAP[key] ?? [];
  for (const legacyKey of legacyKeys) {
    const legacyVal = storage.getItem(legacyKey);
    if (legacyVal !== null) {
      try {
        storage.setItem(key, legacyVal);
      } catch {
        // ignore quota or disabled storage error
      }
      return legacyVal;
    }
  }
  return null;
}

import { beforeEach, describe, expect, it } from "vitest";

import * as storageKeys from "./storageKeys";
import {
  ACTIVE_PROJECT_STORAGE_KEY,
  getMigratedItem,
  NOTIFICATION_SETTINGS_STORAGE_KEY,
  PROJECTS_STORAGE_KEY,
  SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY,
  SIDEBAR_OPEN_STORAGE_KEY,
  SIDEBAR_WIDTH_STORAGE_KEY,
  TERMINAL_SETTINGS_STORAGE_KEY,
} from "./storageKeys";

describe("storageKeys unification and migration", () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it("all storage keys start with ferryx.", () => {
    const keys = [
      PROJECTS_STORAGE_KEY,
      ACTIVE_PROJECT_STORAGE_KEY,
      SIDEBAR_OPEN_STORAGE_KEY,
      SIDEBAR_WIDTH_STORAGE_KEY,
      SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY,
      TERMINAL_SETTINGS_STORAGE_KEY,
      NOTIFICATION_SETTINGS_STORAGE_KEY,
    ];
    for (const key of keys) {
      expect(key.startsWith("ferryx.")).toBe(true);
    }
  });

  it("does not expose a dedicated Quick Commands storage key", () => {
    expect("QUICK_COMMANDS_STORAGE_KEY" in storageKeys).toBe(false);
    const stringValues = Object.values(storageKeys).filter((value) => typeof value === "string");
    expect(stringValues).not.toContain("ferryx.settings.quickCommands");
  });

  it("returns current value when new key exists", () => {
    localStorage.setItem(PROJECTS_STORAGE_KEY, JSON.stringify([{ workspaceId: "proj-1" }]));
    localStorage.setItem("rorca.projects", JSON.stringify([{ workspaceId: "old-proj" }]));

    const result = getMigratedItem(PROJECTS_STORAGE_KEY, localStorage);
    expect(result).toBe(JSON.stringify([{ workspaceId: "proj-1" }]));
  });

  it("migrates legacy key once and persists to new key when new key is absent (F10)", () => {
    localStorage.setItem("rorca.projects", JSON.stringify([{ workspaceId: "legacy-proj" }]));
    expect(localStorage.getItem(PROJECTS_STORAGE_KEY)).toBeNull();

    const result = getMigratedItem(PROJECTS_STORAGE_KEY, localStorage);
    expect(result).toBe(JSON.stringify([{ workspaceId: "legacy-proj" }]));
    expect(localStorage.getItem(PROJECTS_STORAGE_KEY)).toBe(JSON.stringify([{ workspaceId: "legacy-proj" }]));
  });

  it("migrates each defined key from its legacy counterparts", () => {
    localStorage.setItem("orca.sidebar.width", "350");
    expect(getMigratedItem(SIDEBAR_WIDTH_STORAGE_KEY, localStorage)).toBe("350");
    expect(localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY)).toBe("350");

    localStorage.setItem("orca.terminal.settings", JSON.stringify({ fontSize: 16 }));
    expect(getMigratedItem(TERMINAL_SETTINGS_STORAGE_KEY, localStorage)).toBe(JSON.stringify({ fontSize: 16 }));
    expect(localStorage.getItem(TERMINAL_SETTINGS_STORAGE_KEY)).toBe(JSON.stringify({ fontSize: 16 }));

    localStorage.setItem("rorca:settings:notifications:v1", JSON.stringify({ enabled: false }));
    expect(getMigratedItem(NOTIFICATION_SETTINGS_STORAGE_KEY, localStorage)).toBe(JSON.stringify({ enabled: false }));
    expect(localStorage.getItem(NOTIFICATION_SETTINGS_STORAGE_KEY)).toBe(JSON.stringify({ enabled: false }));

    localStorage.setItem("orca.sidebar.open", "false");
    expect(getMigratedItem(SIDEBAR_OPEN_STORAGE_KEY, localStorage)).toBe("false");
    expect(localStorage.getItem(SIDEBAR_OPEN_STORAGE_KEY)).toBe("false");

    localStorage.setItem("rorca.active-project", "project-x");
    expect(getMigratedItem(ACTIVE_PROJECT_STORAGE_KEY, localStorage)).toBe("project-x");
    expect(localStorage.getItem(ACTIVE_PROJECT_STORAGE_KEY)).toBe("project-x");

    localStorage.setItem("rorca.sidebar.collapsedProjects", JSON.stringify(["p1"]));
    expect(getMigratedItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY, localStorage)).toBe(JSON.stringify(["p1"]));
    expect(localStorage.getItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY)).toBe(JSON.stringify(["p1"]));
  });
});

